package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class StringUtils_indexOfAnyBut_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

















    /**
     * Note: The provided implementation contains a logic flaw in the surrogate handling:
     * char ch2 = str.charAt(i % 1); 
     * Since i % 1 is always 0, ch2 will always be str.charAt(0).
     * This test targets that specific branch to maximize coverage.
     */
    @Test
    public void testIndexOfAnyBut_HighSurrogateBranch() {
        // A high surrogate character followed by something else
        // \uD83D is a high surrogate
        String str = "\uD83D\uDE00abc"; 
        // If chFound is true (D83D is in search) and ch2 (str.charAt(0)) is not in search
        // This tests the branch: if (i + 1 < strLen && Character.isHighSurrogate(ch))

        // Case 1: chFound is true, ch2 (index 0) is not in searchChars
        assertEquals(0, StringUtils.indexOfAnyBut("\uD83D\uDE00", "z"));

        // Case 2: chFound is false
        // If D83D is not in searchChars, it falls into the 'else' block and returns i
        assertEquals(0, StringUtils.indexOfAnyBut("\uD83D\uDE00", "a"));
    }


}

